# Code generated by Claude
"""The bench rectangle: where on the bench top the hand can work from one parking spot (overnight queue stage 5, decisions-log M150).

    robot = robot_geometry(model); maps = load_maps("data/reach_map")
    m = measure_rectangle(robot, maps, pedestal_q, cfg=BENCH_RECT_CFG)       # once, offline
    m["rectangle"] -> {"forward_near", "forward_far", "right", "left"} in the base frame facing the bench (x forward, y left), metres, shrunk by the margin

The reachable area at one work height is the set of base-frame (x, y) points whose pad centre can be placed there by either arm in any approach bin (the reach maps' cubes, looked up in the shoulder frame at the
pedestal height); the area for the rectangle is the intersection over the work heights. The rectangle is the largest axis-aligned one inside it (the histogram method), then shrunk by the margin on every side.
Nothing in it is specific to the beaker or the hotplate.

Contents:
    load_maps, largest_rectangle, measure_rectangle, parking_pose, fits.
"""

import math
from pathlib import Path

import numpy as np

from src.reach_map import load_map
from src.task_config import BENCH_RECT_CFG


def load_maps(path):
    """The finished reach maps of a folder: {(side, bin): ReachMap}."""
    maps = {}
    for f in sorted(Path(path).glob("*_bin*.npz")):
        rm = load_map(f)
        maps[(rm.side, rm.bin)] = rm
    return maps


def _area(robot, maps, arms, pedestal_q, top_z, z_rel, xs, ys):
    X, Y = np.meshgrid(xs, ys, indexing="ij")
    out = np.zeros(X.shape, bool)
    q_torso = robot["base_z"] + robot["torso_z0"] + robot["lift_factor"] * pedestal_q
    for arm in arms:
        sx, sy, sz = robot["shoulder"][arm]
        rx, ry = X - sx, Y - sy
        zr = top_z + z_rel - (q_torso + sz)
        for (side, _), rm in maps.items():
            if side != arm:
                continue
            ix = np.floor((rx - rm.origin[0]) / rm.cube).astype(int)
            iy = np.floor((ry - rm.origin[1]) / rm.cube).astype(int)
            iz = int(np.floor((zr - rm.origin[2]) / rm.cube))
            if not 0 <= iz < rm.cubes.shape[2]:
                continue
            inb = (ix >= 0) & (ix < rm.cubes.shape[0]) & (iy >= 0) & (iy < rm.cubes.shape[1])
            hit = np.zeros(X.shape, bool)
            hit[inb] = rm.cubes[ix[inb], iy[inb], iz]
            out |= hit
    return out


def largest_rectangle(mask):
    """The largest axis-aligned all-True rectangle of a bool matrix (the histogram method), ties broken toward the middle of the columns.

    Args:
        mask (numpy.ndarray): Bool (nx, ny).

    Returns:
        tuple or None: (i0, i1, j0, j1) inclusive index ranges along axis 0 and axis 1, or None when the mask is empty.
    """
    nx, ny = mask.shape
    h = np.zeros(ny, int)
    best, best_key = None, None
    for i in range(nx):
        h = np.where(mask[i], h + 1, 0)
        stack = []
        for j in range(ny + 1):
            cur = h[j] if j < ny else 0
            start = j
            while stack and stack[-1][1] >= cur:
                s, hh = stack.pop()
                w = j - s
                if hh > 0:
                    centre_off = abs((s + j - 1) / 2.0 - (ny - 1) / 2.0)
                    key = (hh * w, -centre_off)
                    if best_key is None or key > best_key:
                        best_key, best = key, (i - hh + 1, i, s, j - 1)
                start = s
            stack.append((start, cur))
    return best


def measure_rectangle(robot, maps, pedestal_q, top_z, cfg=BENCH_RECT_CFG, arms=("left", "right"), res=0.01, x_range=(0.0, 1.2), y_range=(-0.8, 0.8)):
    """Measures the bench rectangle.

    Args:
        robot (dict): src/stance_finder.robot_geometry(model).
        maps (dict): {(side, bin): ReachMap}.
        pedestal_q (float): The fixed bench pedestal command, metres.
        top_z (float): The bench top's height above the floor, metres.
        cfg (dict): BENCH_RECT_CFG (work_heights_m, margin_m).
        arms (tuple of str): The arms whose reach is united. Defaults to both.
        res (float): The grid step, metres. Defaults to 0.01.
        x_range, y_range (tuple): The base-frame window searched, metres.

    Returns:
        dict: "rectangle" (the four numbers, shrunk by the margin, or None), "raw" (before the shrink), "mask" (the intersection area), "xs", "ys", "per_height" (bool areas), "area_m2".
    """
    xs = np.arange(x_range[0], x_range[1] + 1e-9, res)
    ys = np.arange(y_range[0], y_range[1] + 1e-9, res)
    per = {z: _area(robot, maps, arms, pedestal_q, top_z, z, xs, ys) for z in cfg["work_heights_m"]}
    mask = np.logical_and.reduce(list(per.values()))
    r = largest_rectangle(mask)
    out = {"mask": mask, "xs": xs, "ys": ys, "per_height": per, "rectangle": None, "raw": None, "area_m2": 0.0}
    if r is None:
        return out
    i0, i1, j0, j1 = r
    raw = {"forward_near": float(xs[i0]), "forward_far": float(xs[i1]), "right": float(ys[j0]), "left": float(ys[j1])}
    m = cfg["margin_m"]
    out["raw"], out["area_m2"] = raw, (raw["forward_far"] - raw["forward_near"]) * (raw["left"] - raw["right"])
    shrunk = {"forward_near": raw["forward_near"] + m, "forward_far": raw["forward_far"] - m, "right": raw["right"] + m, "left": raw["left"] - m}
    if shrunk["forward_far"] > shrunk["forward_near"] and shrunk["left"] > shrunk["right"]:
        out["rectangle"] = {k: round(v, 3) for k, v in shrunk.items()}
    return out


def parking_pose(rect, targets_xy, yaw):
    """The base pose that puts the targets' bounding box in the middle of the rectangle, facing along `yaw` (the heading that faces the bench).

    The rectangle is in the base frame (x forward, y left); the targets' bounding box is centred on the rectangle's centre. Heading and the bench side are the caller's: only the base position is returned.

    Args:
        rect (dict): BENCH_RECT_CFG["rectangle"].
        targets_xy (array-like): (N, 2) world xy of the targets one parking spot must serve.
        yaw (float): The base heading, radians.

    Returns:
        tuple: (x, y, yaw) of the base, and fits (bool): whether the bounding box fits in the rectangle.
    """
    P = np.asarray(targets_xy, float)
    c, s = math.cos(yaw), math.sin(yaw)
    lo, hi = P.min(axis=0), P.max(axis=0)
    centre = (lo + hi) / 2.0
    # the bounding box's extent in the base frame (axis-aligned in the base frame: rotate the points)
    R = np.array([[c, s], [-s, c]])
    B = (P - centre) @ R.T
    ext_f, ext_l = B[:, 0].max() - B[:, 0].min(), B[:, 1].max() - B[:, 1].min()
    mid_f = (rect["forward_near"] + rect["forward_far"]) / 2.0
    mid_l = (rect["left"] + rect["right"]) / 2.0
    bb_mid = np.array([(B[:, 0].max() + B[:, 0].min()) / 2.0, (B[:, 1].max() + B[:, 1].min()) / 2.0])
    # base position: the targets' box centre (centre + R^T bb_mid) sits at (mid_f, mid_l) in the base frame
    box_centre = centre + R.T @ bb_mid
    base = box_centre - R.T @ np.array([mid_f, mid_l])
    fits = ext_f <= rect["forward_far"] - rect["forward_near"] + 1e-9 and ext_l <= rect["left"] - rect["right"] + 1e-9
    return (float(base[0]), float(base[1]), float(yaw)), bool(fits)


def fits(rect, base_pose, targets_xy):
    """Whether every target lies inside the rectangle from a base pose (x, y, yaw)."""
    x, y, yaw = base_pose
    c, s = math.cos(yaw), math.sin(yaw)
    for tx, ty in np.asarray(targets_xy, float):
        f, l = c * (tx - x) + s * (ty - y), -s * (tx - x) + c * (ty - y)
        if not (rect["forward_near"] <= f <= rect["forward_far"] and rect["right"] <= l <= rect["left"]):
            return False
    return True
